#!/usr/bin/env python3
import sys, os, json, subprocess, re, tempfile, shlex

# Helper to get help, version, build config strings exactly as observed
HELP_TEXT = """jq - commandline JSON processor [version build-f77602d]

Usage:\tjq [options] <jq filter> [file...]
\tjq [options] --args <jq filter> [strings...]
\tjq [options] --jsonargs <jq filter> [JSON_TEXTS...]

jq is a tool for processing JSON inputs, applying the given filter to
its JSON text inputs and producing the filter's results as JSON on
standard output.

The simplest filter is ., which copies jq's input to its output
unmodified except for formatting. For more advanced filters see
the jq(1) manpage ("man jq") and/or https://jqlang.org/.

Example:

\t$ echo '{"foo": 0}' | jq .
\t{
\t  "foo": 0
\t}

Command options:
  -n, --null-input          use `null` as the single input value;
  -R, --raw-input           read each line as string instead of JSON;
  -s, --slurp               read all inputs into an array and use it as
                            the single input value;
  -c, --compact-output      compact instead of pretty-printed output;
  -r, --raw-output          output strings without escapes and quotes;
      --raw-output0         implies -r and output NUL after each output;
  -j, --join-output         implies -r and output without newline after
                            each output;
  -a, --ascii-output        output strings by only ASCII characters
                            using escape sequences;
  -S, --sort-keys           sort keys of each object on output;
  -C, --color-output        colorize JSON output;
  -M, --monochrome-output   disable colored output;
      --tab                 use tabs for indentation;
      --indent n            use n spaces for indentation (max 7 spaces);
      --unbuffered          flush output stream after each output;
      --stream              parse the input value in streaming fashion;
      --stream-errors       implies --stream and report parse error as
                            an array;
      --seq                 parse input/output as application/json-seq;
  -f, --from-file           load the filter from a file;
  -L, --library-path dir    search modules from the directory;
      --arg name value      set $name to the string value;
      --argjson name value  set $name to the JSON value;
      --slurpfile name file set $name to an array of JSON values read
                            from the file;
      --rawfile name file   set $name to string contents of file;
      --args                consume remaining arguments as positional
                            string values;
      --jsonargs            consume remaining arguments as positional
                            JSON values;
  -e, --exit-status         set exit status code based on the output;
  -V, --version             show the version;
  --build-configuration     show jq's build configuration;
  -h, --help                show the help;
  --                        terminates argument processing;

Named arguments are also available as $ARGS.named[], while
positional arguments are available as $ARGS.positional[].
"""

VERSION_TEXT = "jq-build-f77602d\n"
BUILD_TEXT = "--disable-docs --with-oniguruma=builtin --enable-static --enable-all-static --prefix=/usr/local\n"

# For error prefix handling
def eprint(msg):
    sys.stderr.write(msg)

def print_help():
    sys.stdout.write(HELP_TEXT)
    sys.exit(0)

def print_version():
    sys.stdout.write(VERSION_TEXT)
    sys.exit(0)

def print_build():
    sys.stdout.write(BUILD_TEXT)
    sys.exit(0)

def error_exit(msg, code=2):
    # msg should already have newline
    eprint(msg)
    sys.exit(code)

# We'll parse args manually
def parse_args(argv):
    # argv includes program name at 0
    # returns dict
    opts = {
        'null_input': False,
        'raw_input': False,
        'slurp': False,
        'compact': False,
        'raw_output': False,
        'raw_output0': False,
        'join_output': False,
        'ascii_output': False,
        'sort_keys': False,
        'color': None, # None auto, True force, False monochrome
        'tab': False,
        'indent': None, # None default 2 spaces? Actually default pretty is 2 spaces
        'unbuffered': False,
        'stream': False,
        'stream_errors': False,
        'seq': False,
        'from_file': None,
        'library_path': [],
        'args': [], # list of (name, value, is_json, is_slurp, is_raw)
        # but we need separate for arg, argjson, slurpfile, rawfile
        'arg_vars': {}, # name -> (value, is_json)
        'slurpfile_vars': {}, # name -> file
        'rawfile_vars': {}, # name -> file
        'exit_status': False,
        'filter': None,
        'filter_file': None,
        'input_files': [],
        'positional_args': [], # for --args / --jsonargs mode
        'args_mode': None, # None, 'args', 'jsonargs'
    }
    # Also need to track if -- was encountered
    # We'll iterate
    args = argv[1:]
    i = 0
    # To handle combined shorts like -cS or -Rs etc, we need to expand
    # But we can handle iterative char by char for short options that don't take args
    # Short options that take args: -f, -L
    # Others are flags
    # Combined shorts: -cR, -n, -R, -s, -c, -r, -j, -a, -S, -C, -M, -e, -V, -h
    # Need to handle them.

    # First, we need to handle --args and --jsonargs specially: they consume remaining arguments as positional values, not files.
    # The filter is before them? Usage: jq [options] --args <jq filter> [strings...]
    # So if --args appears, the next argument is the filter, and remaining are positional args.

    # Also need to handle -- as terminator

    # We'll parse step by step
    positionals = []  # collected non-option arguments after parsing options

    while i < len(args):
        a = args[i]
        if a == '--':
            # terminator: rest are positionals
            positionals.extend(args[i+1:])
            break
        elif a == '--help' or a == '-h':
            print_help()
        elif a == '--version' or a == '-V':
            print_version()
        elif a == '--build-configuration':
            print_build()
        elif a in ('-n', '--null-input'):
            opts['null_input'] = True
            i += 1
            continue
        elif a in ('-R', '--raw-input'):
            opts['raw_input'] = True
        elif a in ('-s', '--slurp'):
            opts['slurp'] = True
        elif a in ('-c', '--compact-output'):
            opts['compact'] = True
        elif a in ('-r', '--raw-output'):
            opts['raw_output'] = True
        elif a == '--raw-output0':
            opts['raw_output0'] = True
            opts['raw_output'] = True
        elif a in ('-j', '--join-output'):
            opts['join_output'] = True
            opts['raw_output'] = True
        elif a in ('-a', '--ascii-output'):
            opts['ascii_output'] = True
        elif a in ('-S', '--sort-keys'):
            opts['sort_keys'] = True
        elif a in ('-C', '--color-output'):
            opts['color'] = True
        elif a in ('-M', '--monochrome-output'):
            opts['color'] = False
        elif a == '--tab':
            opts['tab'] = True
            opts['indent'] = None  # tab overrides indent? Actually handled later: tab uses tab char, indent is ignored
        elif a == '--indent':
            # requires one param
            if i+1 >= len(args):
                error_exit("jq: --indent takes one parameter\nUse jq --help for help with command-line options,\nor see the jq manpage, or online docs at https://jqlang.org\n", 2)
            val = args[i+1]
            i += 1
            # validate
            try:
                n = int(val)
            except:
                error_exit("jq: --indent takes a number between -1 and 7\nUse jq --help for help with command-line options,\nor see the jq manpage, or online docs at https://jqlang.org\n", 2)
            if n < -1 or n > 7:
                error_exit("jq: --indent takes a number between -1 and 7\nUse jq --help for help with command-line options,\nor see the jq manpage, or online docs at https://jqlang.org\n", 2)
            opts['indent'] = n
        elif a.startswith('--indent='):
            error_exit(f"jq: Unknown option {a}\nUse jq --help for help with command-line options,\nor see the jq manpage, or online docs at https://jqlang.org\n", 2)
        elif a == '--unbuffered':
            opts['unbuffered'] = True
        elif a == '--stream':
            opts['stream'] = True
        elif a == '--stream-errors':
            opts['stream_errors'] = True
            opts['stream'] = True
        elif a == '--seq':
            opts['seq'] = True
        elif a in ('-f', '--from-file'):
            if i+1 >= len(args):
                error_exit("jq: --from-file takes one parameter\nUse jq --help for help with command-line options,\nor see the jq manpage, or online docs at https://jqlang.org\n", 2)
            # In original, -f takes param like -f/tmp/file? We need handle attached
            # But above we handled only separate param. Handle attached for -f and -L
            # Actually we are in branch for exact '-f' or '--from-file', so param is next arg
            opts['filter_file'] = args[i+1]
            # We'll later load filter from file; also need to ensure file exists now? For error handling, if file not found, exit 2 with message "jq: Could not open ..."
            # But we delay until later? Original does: if -f file not found, prints "jq: Could not open ..." and exit 2, without trying to compile filter.
            # We'll handle after parsing.
            i += 1
        elif a.startswith('-f'):
            # attached like -f/tmp/file or -ffile
            if a == '-f':
                # handled above, but we are here due to elif chain? Actually we handled '-f' exact above, so this elif is for a.startswith but not equal?
                pass
            else:
                # Extract file after -f
                fname = a[2:]
                if fname == "":
                    # This would be "-f" alone, handled above, but we are here: maybe "-f" with no chars after, but we already handled, so not happen
                    error_exit("-f takes a parameter: (e.g. -f file) \nUse ...", 2)
                opts['filter_file'] = fname
        elif a in ('-L', '--library-path'):
            if i+1 >= len(args):
                error_exit("-L takes a parameter: (e.g. -L /search/path or -L/search/path)\nUse jq --help for help with command-line options,\nor see the jq manpage, or online docs at https://jqlang.org\n", 2)
            opts['library_path'].append(args[i+1])
            i += 1
        elif a.startswith('-L'):
            if a == '-L':
                # handled above
                pass
            else:
                fname = a[2:]
                if fname != "":
                    opts['library_path'].append(fname)
                else:
                    error_exit("-L takes a parameter: (e.g. -L /search/path or -L/search/path)\nUse jq --help for help with command-line options,\nor see the jq manpage, or online docs at https://jqlang.org\n", 2)
        elif a == '--arg':
            if i+2 >= len(args):
                error_exit("jq: --arg takes two parameters (e.g. --arg varname value)\nUse jq --help for help with command-line options,\nor see the jq manpage, or online docs at https://jqlang.org\n", 2)
            name = args[i+1]
            value = args[i+2]
            opts['arg_vars'][name] = value
            # also need to track named args for $ARGS.named
            i += 2
        elif a == '--argjson':
            if i+2 >= len(args):
                error_exit("jq: --argjson takes two parameters (e.g. --argjson varname text)\nUse jq --help for help with command-line options,\nor see the jq manpage, or online docs at https://jqlang.org\n", 2)
            name = args[i+1]
            value = args[i+2]
            # Validate value is JSON
            try:
                json.loads(value)
            except:
                error_exit("jq: invalid JSON text passed to --argjson\nUse jq --help for help with command-line options,\nor see the jq manpage, or online docs at https://jqlang.org\n", 2)
            opts['arg_vars'][name] = (value, True)  # mark as json
            # For --argjson, we store differently
            # Let's store in a dict with flag
            if 'argjson_vars' not in opts:
                opts['argjson_vars'] = {}
            opts['argjson_vars'][name] = value
            i += 2
        elif a == '--slurpfile':
            if i+2 >= len(args):
                error_exit("jq: --slurpfile takes two parameters (e.g. --slurpfile varname filename)\nUse jq --help for help with command-line options,\nor see the jq manpage, or online docs at https://jqlang.org\n", 2)
            name = args[i+1]
            fname = args[i+2]
            # Check file exists and is valid JSON array? Actually if file missing, error "Bad JSON in --slurpfile ..."
            # We'll validate later
            opts['slurpfile_vars'][name] = fname
            i += 2
        elif a == '--rawfile':
            if i+2 >= len(args):
                error_exit("jq: --rawfile takes two parameters (e.g. --rawfile varname filename)\nUse jq --help for help with command-line options,\nor see the jq manpage, or online docs at https://jqlang.org\n", 2)
            name = args[i+1]
            fname = args[i+2]
            opts['rawfile_vars'][name] = fname
            i += 2
        elif a == '--args':
            opts['args_mode'] = 'args'
            # The filter will be next positional, rest are positional args
            # But we need to continue parsing? After --args, remaining args are not options, they are filter and strings
            # So we break and treat next as filter and rest as positional_args
            positionals.extend(args[i+1:])
            # We'll handle after loop
            i = len(args)
            break
        elif a == '--jsonargs':
            opts['args_mode'] = 'jsonargs'
            positionals.extend(args[i+1:])
            i = len(args)
            break
        elif a in ('-e', '--exit-status'):
            opts['exit_status'] = True
        elif a.startswith('-') and not a.startswith('--'):
            # Combined short options
            # Need to handle like -cS, -Rs, -ce etc. Also handle -f and -L with attached values inside combo?
            # For simplicity, iterate chars after '-'
            # If any char is unknown, error
            # For -f and -L, they take param: if they appear in combo, the rest of the arg is the param or next arg is param.
            # Example: -L/tmp -> we already handled via startswith('-L') above, but that would be caught before here? Our earlier checks for '-L' prefix would have captured, but this branch is for generic short combo.
            # We need to decide: handle before this generic branch.

            # We'll process char by char
            # But we already handled exact single flags above; for combo we need to fallback
            # If a is like "-cS", it didn't match any previous elif, so it comes here.
            # We'll iterate
            j = 1
            consumed_next = False
            while j < len(a):
                ch = a[j]
                if ch == 'n':
                    opts['null_input'] = True
                elif ch == 'R':
                    opts['raw_input'] = True
                elif ch == 's':
                    opts['slurp'] = True
                elif ch == 'c':
                    opts['compact'] = True
                elif ch == 'r':
                    opts['raw_output'] = True
                elif ch == 'j':
                    opts['join_output'] = True
                    opts['raw_output'] = True
                elif ch == 'a':
                    opts['ascii_output'] = True
                elif ch == 'S':
                    opts['sort_keys'] = True
                elif ch == 'C':
                    opts['color'] = True
                elif ch == 'M':
                    opts['color'] = False
                elif ch == 'e':
                    opts['exit_status'] = True
