                        opts['filter_file'] = args[i+1]
                        consumed_next = True
                    break  # after f, stop processing this arg
                elif ch == 'L':
                    remainder = a[j+1:]
                    if remainder != "":
                        opts['library_path'].append(remainder)
                    else:
                        if i+1 >= len(args):
                            error_exit("-L takes a parameter: (e.g. -L /search/path or -L/search/path)\nUse jq --help for help with command-line options,\nor see the jq manpage, or online docs at https://jqlang.org\n", 2)
