                        consumed_next = True
                    break
                else:
                    error_exit(f"jq: Unknown option -{ch}\nUse jq --help for help with command-line options,\nor see the jq manpage, or online docs at https://jqlang.org\n", 2)
                j += 1
            if consumed_next:
                i += 1
        elif a.startswith('-'):
            # Unknown option
            error_exit(f"jq: Unknown option {a}\nUse jq --help for help with command-line options,\nor see the jq manpage, or online docs at https://jqlang.org\n", 2)
        else:
            # positional argument (filter or file)
            positionals.append(a)
        i += 1

    # After loop, handle positionals based on mode
    # Need to determine filter and input files
    if opts['filter_file'] is not None:
        # Filter is from file, positionals are all input files (or positional args if args_mode)
        if opts['args_mode'] is not None:
