        if opts['args_mode'] is not None:
            # Need filter
            if len(positionals) == 0:
                error_exit("jq: error: Top-level program not given (try \".\")\njq: 1 compile error\n", 3)
            opts['filter'] = positionals[0]
            opts['positional_args'] = positionals[1:]
            opts['input_files'] = []
            # Validate jsonargs if needed
            if opts['args_mode'] == 'jsonargs':
                for val in opts['positional_args']:
                    try:
                        json.loads(val)
                    except:
                        # What is error for invalid jsonargs? Need to check. Probably similar to --argjson invalid?
                        # Let's test via executable: ./executable -n --jsonargs '$ARGS' invalid 2>&1
                        # We didn't test. For now assume we need to error with something.
                        # But we can leave validation to subprocess; system will error accordingly, but we need to ensure error matches new's format.
                        # For now, just continue and let delegation handle; but new's behavior for invalid jsonargs? Let's test later
                        pass
            # Also need to handle empty filter?
            if opts['filter'].strip() == "":
                error_exit("jq: error: Top-level program not given (try \".\")\njq: 1 compile error\n", 3)
        else:
            # Normal mode: first positional is filter, rest are files
            if len(positionals) == 0:
                # No filter provided, defaults to "."
                opts['filter'] = "."
                opts['input_files'] = []
            elif len(positionals) == 1:
                # Could be filter, no files
                # But what about case where filter is default and there's a file? The condition len==1 could be either filter or file with default filter
                # However according to docs, filter is required. The default '.' only when no positional given.
                # So with one positional, it's the filter.
                opts['filter'] = positionals[0]
                opts['input_files'] = []
                if opts['filter'].strip() == "":
                    error_exit("jq: error: Top-level program not given (try \".\")\njq: 1 compile error\n", 3)
            else:
                opts['filter'] = positionals[0]
                opts['input_files'] = positionals[1:]
                if opts['filter'].strip() == "":
                    error_exit("jq: error: Top-level program not given (try \".\")\njq: 1 compile error\n", 3)
