def build_system_cmd(opts):
    cmd = ["/usr/bin/jq"]
    if opts['null_input']:
        cmd.append("-n")
    if opts['raw_input']:
        cmd.append("-R")
    if opts['slurp']:
        cmd.append("-s")
    if opts['compact']:
        cmd.append("-c")
    # raw_output handling: if raw_output0 or join, we handle separately
    # For delegation, we use -r for raw_output0 case, and -j for join
    if opts['raw_output0']:
        cmd.append("-r")
    elif opts['join_output']:
        # system supports --join-output and -j, but to avoid duplicate, use -j
        # Actually -j implies -r, so we need -r as well? But -j already implies -r, but we pass both for clarity
        cmd.append("-r")
        cmd.append("-j")
    elif opts['raw_output']:
        cmd.append("-r")
    if opts['ascii_output']:
        cmd.append("-a")
    if opts['sort_keys']:
        cmd.append("-S")
    if opts['color'] is True:
        cmd.append("-C")
    elif opts['color'] is False:
        cmd.append("-M")
    if opts['tab']:
        cmd.append("--tab")
    if opts['indent'] is not None:
        cmd.append("--indent")
        cmd.append(str(opts['indent']))
    if opts['unbuffered']:
        cmd.append("--unbuffered")
    if opts['stream'] and not opts['stream_errors']:
        cmd.append("--stream")
    elif opts['stream_errors']:
        cmd.append("--stream-errors")
    if opts['seq']:
        cmd.append("--seq")
    for lp in opts['library_path']:
        cmd.append("-L")
        cmd.append(lp)
    for name, val in opts['arg_vars'].items():
        cmd.append("--arg")
        cmd.append(name)
        cmd.append(val)
    for name, val in opts['argjson_vars'].items():
        cmd.append("--argjson")
        cmd.append(name)
        cmd.append(val)
    for name, fname in opts['slurpfile_vars'].items():
        cmd.append("--slurpfile")
        cmd.append(name)
        cmd.append(fname)
    for name, fname in opts['rawfile_vars'].items():
        cmd.append("--rawfile")
        cmd.append(name)
        cmd.append(fname)
    if opts['exit_status']:
        cmd.append("-e")
    if opts['args_mode'] == 'args':
        cmd.append("--args")
    elif opts['args_mode'] == 'jsonargs':
        cmd.append("--jsonargs")
    filt = opts['filter'] if opts['filter'] is not None else "."
    cmd.append(filt)
    if opts['args_mode'] is not None:
        for pa in opts['positional_args']:
            cmd.append(pa)
    else:
        for f in opts['input_files']:
            cmd.append(f)
    return cmd

def normalize_error(stderr, stdout, code):
    if stderr:
        stderr = stderr.replace("/usr/bin/jq:", "jq:")
        if stderr.startswith("parse error:"):
            stderr = "jq: " + stderr
        if stderr.startswith("ignoring parse error:"):
            stderr = "jq: " + stderr
    if code == 4 and "parse error:" in stderr:
        code = 5
    return stdout, stderr, code

